+// The audit trail: one entry for every request that changes data.
+
+/** Appends an audit entry (time, key name, method, path, status). */
+export function record(store, { at, name, method, path, status }) {
+  const entry = { id: store.nextId("audit"), at, name, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** All audit entries, newest first. */
+export function list(store) {
+  return [...store.data.audit].reverse();
+}
