+// API keys and roles. A key is { key, name, role } in the store's `apiKeys`.
+import { AppError } from "../errors.js";
+
+const COOK_ROUTES = [
+  ["POST", /^\/recipes\/[^/]+\/cook$/],
+  ["POST", /^\/batches\/[^/]+\/waste$/],
+  ["POST", /^\/temperatures$/],
+  ["POST", /^\/stocktakes\/[^/]+\/counts$/],
+];
+
+/** Finds the key record for the Authorization header or throws `unauthorized`. */
+export function authenticate(store, headers) {
+  const name = Object.keys(headers).find((h) => h.toLowerCase() === "authorization");
+  const m = /^Bearer\s+(\S+)$/i.exec(String(name ? headers[name] : ""));
+  const found = m && store.data.apiKeys.find((k) => k.key === m[1]);
+  if (!found) throw new AppError("unauthorized");
+  return found;
+}
+
+/** Throws `forbidden` unless the key's role may make this request. */
+export function authorize(apiKey, method, path) {
+  const { role } = apiKey;
+  if (role === "manager") return;
+  if (path === "/audit") throw new AppError("forbidden");
+  if (method === "GET") {
+    if (role === "viewer" || role === "cook") return;
+  } else if (role === "cook" && COOK_ROUTES.some(([m, re]) => m === method && re.test(path))) return;
+  throw new AppError("forbidden");
+}
